export function createMcpApp(options: CreateMcpAppOptions = {}) {
  const app = new Hono<McpEnvironment>();
  const getServices =
    options.getServices ?? createApiServiceProvider({ authentication: "oauth-only" });
  const now = options.now ?? (() => new Date());
  const resolvePostHog = createPostHogResolver(options.posthog);
  const writer = new WeakMap<ApiServices, McpAuditWriter>();
  const auditFor = (services: ApiServices): McpAuditWriter => {
    const existing = writer.get(services);
    if (existing) return existing;
    const role = services.database.role;
    const created =
      options.createAuditWriter?.(services) ??
      (role === "control"
        ? new ControlPlaneMcpAuditWriter(services.database.pool)
        : new PostgresMcpAuditWriter(services.database.pool, role === "regional"));
    writer.set(services, created);
    return created;
  };

  const metadata = (bindings: RuntimeBindings | undefined) =>
    protectedResourceMetadata(
      bindings?.RUNTIME_ENV
        ? parseOAuthEndpoints(bindings)
        : { issuer: MCP_ISSUER, resource: MCP_RESOURCE },
    );
  app.get("/.well-known/oauth-protected-resource", (context) =>
    metadataResponse(metadata(context.env)),
  );
  app.get("/.well-known/oauth-protected-resource/mcp", (context) =>
    metadataResponse(metadata(context.env)),
  );
  app.get(
    "/",
    () =>
      new Response(MCP_HOME, {
        headers: {
          "cache-control": "public, max-age=3600",
          "content-type": "text/html; charset=utf-8",
          "x-content-type-options": "nosniff",
        },
      }),
  );
  app.get("/favicon.ico", () => brandAssetResponse(favicon, "image/x-icon"));
  app.get("/favicon-32x32.png", () => brandAssetResponse(favicon32, "image/png"));
  app.get("/apple-touch-icon.png", () =>
    brandAssetResponse(appleTouchIcon, "image/png"),
  );
  app.get("/icon-192.png", () => brandAssetResponse(icon192, "image/png"));
  app.get("/icon-512.png", () => brandAssetResponse(icon512, "image/png"));
  app.get("/skillplane-logo-gradient-transparent.png", () =>
    brandAssetResponse(gradientLogo, "image/png"),
  );
  app.get(
    "/site.webmanifest",
    () =>
      new Response(MCP_MANIFEST, {
        headers: {
          "cache-control": BRAND_CACHE_CONTROL,
          "content-type": "application/manifest+json",
          "x-content-type-options": "nosniff",
        },
      }),
  );

  app.all("/mcp", async (context) => {
    let services: ApiServices | null = null;
        identity,
        auditFor(services),
        now,
      );
    } catch (error) {
      if (error instanceof McpAuthenticationError) {
        return mcpAuthenticationResponse(services, error);
      }
      return jsonError(500, "INTERNAL_ERROR", "The download could not be completed");
    } finally {
      if (services) {
        try {
          await getServices.release?.(services);
        } catch {
          console.error(
            JSON.stringify({
              component: "mcp",
              event: "mcp.services.release.failed",
            }),
          );
        }
      }
    }
  });

  app.notFound(() =>
    jsonError(404, "NOT_FOUND", "The requested MCP route was not found"),
  );
  return app;
}

const services = createApiServiceProvider({ authentication: "oauth-only" });
export const app = createMcpApp({ getServices: services });
const routedApp = createRoutedMcpApplication({ local: app, services });

interface WorkerHandler<Bindings> {
  fetch(
    request: Request,
    environment: Bindings,
    context: {
      waitUntil(promise: Promise<unknown>): void;
      passThroughOnException(): void;
      readonly props: unknown;
    },
  ): Response | Promise<Response>;
}

export default {
  fetch(request, environment, context) {
    return routedApp.fetch(request, environment, context);
  },
} satisfies WorkerHandler<RuntimeBindings>;
import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { renderDevelopmentTopologyConfigs } from "./render-development-topology-config.mjs";
import { assertDevelopmentControlDatabaseShape } from "./prepare-development-topology-databases.mjs";
import { parseOnlyKinds } from "./deploy-development-topology.mjs";
import { selectDevelopmentTopologyOutputs } from "./lib/development-topology-deployment.mjs";

const ids = {
  control: "1".repeat(32),
  inSouth: "2".repeat(32),
  usEast: "3".repeat(32),
  euWest: "4".repeat(32),
};

describe("multi-cell development deployment", () => {
  it("rejects invalid deployment selections before starting deployment", () => {
    assert.throws(
      () => parseOnlyKinds(["--only", "app,ap"]),
      /--only must contain app, mcp, projection, or datafn/u,
    );
    assert.deepEqual(parseOnlyKinds(["--only", "app,datafn"]), ["app", "datafn"]);
  });

  it("renders isolated gateways and three private regional cells", async () => {
    const rendered = await renderDevelopmentTopologyConfigs({
      controlHyperdriveId: ids.control,
      publicBucketName: "skillplane-public-bundles-dev",
      publicTurnstileSiteKey: "development-turnstile-site-key",
      postHogProjectToken: `phc_${"d".repeat(32)}`,
      cells: {
        "in-south": {
          hyperdriveId: ids.inSouth,
          bucketName: "skillplane-skill-bundles-dev",
        },
        "us-east": {
          hyperdriveId: ids.usEast,
          bucketName: "skillplane-us-east-bundles-dev",
        },
        "eu-west": {
          hyperdriveId: ids.euWest,
          bucketName: "skillplane-eu-west-bundles-dev",
        },
      },
      write: false,
    });

    assert.equal(rendered.outputs.length, 14);
    const canary = selectDevelopmentTopologyOutputs(rendered.outputs, [
      "app",
      "datafn",
    ]);
    assert.equal(canary.length, 7);
    assert.deepEqual(
      canary.map((output) => output.kind),
      ["app", "datafn", "app", "datafn", "app", "datafn", "app"],
    );
    assert.equal(canary.at(-1)?.id, "gateway:app");
    const gatewayApp = rendered.outputs.find((output) => output.id === "gateway:app");
    const gatewayMcp = rendered.outputs.find((output) => output.id === "gateway:mcp");
    assert.equal(gatewayApp.config.name, "skillplane-app-dev");
    assert.equal(gatewayApp.config.routes[0].pattern, "app-dev.skillplane.dev");
    assert.equal(gatewayApp.config.vars.RUNTIME_ENV, "preview");
    assert.equal(
      gatewayApp.config.services.find(
        (service) => service.binding === "CELL_EU_WEST_APP",
      )?.service,
      "skillplane-app-dev-eu-west",
    );
    assert.equal(gatewayMcp.config.name, "skillplane-mcp-dev");
    assert.equal(gatewayMcp.config.routes[0].pattern, "mcp-dev.skillplane.dev");

    for (const output of rendered.outputs.filter((item) => item.regionId)) {
      if (output.kind === "datafn") {
        assert.equal(
          output.config.routes[0].pattern,
          `datafn-${output.regionId}-dev.skillplane.dev`,
        );
      } else {
        assert.equal(output.config.routes, undefined);
      }
      assert.equal(output.config.workers_dev, false);
      assert.equal(output.config.vars.RUNTIME_ENV, "preview");
      assert.equal(output.config.vars.SKILLPLANE_REGION_ID, output.regionId);
    }
  });

  it("rejects a Hyperdrive reused across control and cells", async () => {
    await assert.rejects(
      renderDevelopmentTopologyConfigs({
