const assignmentPattern =
  /^(?<prefix>\s*(?:export\s+)?)(?<name>[A-Za-z_][A-Za-z0-9_]*)=(?<value>.*)$/u;

function validateAssignment(name, value) {
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/u.test(name)) {
    throw new Error(`Invalid local Worker variable name: ${name}`);
